// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract GuardedWithdraw {
    mapping(address => uint256) public balances;
    uint256 private _lock = 1;

    modifier nonReentrant() {
        require(_lock == 1, "reentrant");
        _lock = 2;
        _;
        _lock = 1;
    }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw() external nonReentrant {
        uint256 bal = balances[msg.sender];
        require(bal > 0, "nothing to withdraw");
        balances[msg.sender] = 0;            // effect FIRST
        (bool ok, ) = msg.sender.call{value: bal}("");
        require(ok, "transfer failed");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract PullPaymentSplitter {
    mapping(address => uint256) public owed;
    uint256 public totalOwed;

    function credit(address who) external payable {
        require(who != address(0), "zero address");
        owed[who] += msg.value;
        totalOwed += msg.value;
    }

    function claim() external {
        uint256 amount = owed[msg.sender];
        require(amount > 0, "nothing owed");
        owed[msg.sender] = 0;
        totalOwed -= amount;
        payable(msg.sender).transfer(amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SafeVault {
    address public immutable owner;
    mapping(address => uint256) public balances;
    constructor() { owner = msg.sender; }

    modifier onlyOwner() { require(msg.sender == owner, "not owner"); _; }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(balances[msg.sender] >= amount, "insufficient");
        balances[msg.sender] -= amount;            // effects BEFORE interaction
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }

    function sweepDust(address payable to) external onlyOwner {
        to.transfer(address(this).balance);
    }
    receive() external payable {}
}

